@dataclass(frozen=True)
class TerminalGateEvidence:
    module: Path
    facade: Path
    theorem: str
    scope: str
    expected_type_fragment: str


def contains_lean_proof_placeholder(source: str) -> bool:
    """Detect proof placeholders in Lean code, ignoring comments and strings."""
    code: list[str] = []
    index = 0
    block_depth = 0
    in_line_comment = False
    in_string = False
    while index < len(source):
        pair = source[index : index + 2]
        char = source[index]
        if in_line_comment:
            if char == "\n":
                in_line_comment = False
                code.append(char)
            index += 1
        elif block_depth:
            if pair == "/-":
                block_depth += 1
                index += 2
            elif pair == "-/":
                block_depth -= 1
                index += 2
            else:
                index += 1
        elif in_string:
            if char == "\\":
                index += 2
            else:
                in_string = char != '"'
                index += 1
        elif pair == "--":
            in_line_comment = True
            index += 2
        elif pair == "/-":
            block_depth = 1
            index += 2
        elif char == '"':
            in_string = True
            index += 1
        else:
            code.append(char)
            index += 1
    return re.search(r"\b(?:sorry|admit|axiom)\b", "".join(code)) is not None


